local TimeUtils = CS.Engine.Tools.TimeUtils
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数

local ActivityParamsDefine = {
    RESTORE_HP_INTERVAL  = 1, -- 恢复活动体力所需秒数
    RESTORE_NUM          = 2, -- 活动体力每次恢复X点
    HP_UP_LIMIT          = 3, -- 活动体力恢复上限
    BUY_CONSUME_ITEM     = 4, -- 兑换体力用道具id
    BUY_CONSUME_ITEM_NUM = 5, -- 消耗道具的数量（从左至右依次递增。到最右后循环）
    BUY_NUM              = 6, -- 消耗道具可兑换的体力数量
    BUY_DAILY_TIME_LIMIT = 7, -- 每日活动体力最多可兑换次数
}

---@class MidFestivalHomeDojo
local MidFestivalHomeDojo = Class("MidFestivalHomeDojo")

function MidFestivalHomeDojo:__init()
    self.mapQuest = {
        questId = 0,    --- 关卡id
        status = 0,     --- 0未解锁 1已解锁 2已通关
        unlockDate = 0, --- 解锁日期
        unlockCountdown = 0, --- 大于0开启的倒计时 小于0 已经开启的时间
    }    --- 关卡信息
    self.repaintingQuest = {
        questId = 0,    --- 复刷关卡ID
        status = 0,     --- 0未解锁 1已解锁 2已通关
        isPassed = 0    --- 是否已经通关
    }
    self.mainQuestHash = {}     --- 主线关卡Hash表
    self.repaintingQuestHash = {}   --- 复刷关卡Hash表
    self.mainQuestId = 0  --- 当前通关的主线关卡最新id
    self.taskAllCount = 0   --- 任务总数
    self.taskPassCount = 0  --- 任务通关数量
    self.mallRemainTime = 0 --- 商店剩余时间
    self.taskTips = 0       --- 0有小红点 -1没有小红点
    self.bossHurtTips = -1   --- 0有小红点 -1没有小红点
    self.achievementTaskTips = -1 ---0有小红点 -1没有小红点
    self.scheduleConf = {}
    self.entranceConf = {}
    self.hpData = {
        lastCdTime = 0,     --- 下一次恢复剩余的秒数，为0表示已经恢复满
        hp = 0              --- 用户当前服务器中的体力
    }
    self.dailyBuyHpTimes = 0 --- 每日体力购买次数
    self.nextRecoveryTime = 0
end

function MidFestivalHomeDojo:__delete()
    self:RemoveTimer()
    self.mapQuest = nil
    self.repaintingQuest = nil
    self.mainQuestHash = nil
    self.repaintingQuestHash = nil
    self.mainQuestId = nil
    self.taskAllCount = nil
    self.taskPassCount = nil
    self.mallRemainTime = nil
    self.taskTips = nil
    self.bossHurtTips = nil
    self.scheduleConf = nil
    self.entranceConf = nil
    self.hpData = nil
    self.dailyBuyHpTimes = nil
    self.nextRecoveryTime = nil
end

---Update
---更新数据
---@param jsonData table
function MidFestivalHomeDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
        end
    end

    for i, v in ipairs(self.mapQuest) do
        self.mainQuestHash[checkString(v.questId)] = v
    end

    for i, v in ipairs(self.repaintingQuest) do
        self.repaintingQuestHash[checkString(v.questId)] = v
    end
    
    local data = {}
    for i, v in pairs(self.entranceConf) do
        table.insert(data,v)
    end
    table.sort(data,function(a,b) return a.id < b.id  end)
    self.entranceConf = data
    self._hpMax = checkNumber(self:GetConfigParamsById(ActivityParamsDefine.HP_UP_LIMIT))
    self._hpRecoverSeconds = checkNumber(self:GetConfigParamsById(ActivityParamsDefine.RESTORE_HP_INTERVAL))
    self._recoveryHpPerTime = self:GetConfigParamsById(ActivityParamsDefine.RESTORE_NUM)
    local serverTime = GameUtils.GetServerTime()
    self.mallRemainTime = self.mallRemainTime + serverTime

    self:StartTimeDown()
end

function MidFestivalHomeDojo:UpdateMapQuestStatus(mapQuestId, status)
    local mapQuest = self.mainQuestHash[checkString(mapQuestId)]
    if isNull(mapQuest) then
        return
    end
    mapQuest.status = status
    for _, mapQuest in ipairs(self.mapQuest) do
        if checkString(mapQuestId) == checkString(mapQuest.questId) then
            mapQuest.status = status
        end
    end
end

function MidFestivalHomeDojo:UpdateRecordStatus(questId, status)
    local repaintQuest = self.repaintingQuestHash[checkString(questId)]
    if isNull(repaintQuest) then
        return
    end
    repaintQuest.status = status
    for _, repaintQuest in ipairs(self.repaintingQuest) do
        if checkString(questId) == checkString(repaintQuest.questId) then
            repaintQuest.status = status
        end
    end
end

function MidFestivalHomeDojo:IsReachUnlockDate(mapId)
    local placeDojo = self.mainQuestHash[checkString(mapId)]
    if isNull(placeDojo) then
        return false
    end
    return checkNumber(placeDojo.unlockCountdown) < 0
end

function MidFestivalHomeDojo:TimeCountDownTips(mapId)
    local tipInfo = ""
    local placeDojo = self.mainQuestHash[checkString(mapId)]
    if isNull(placeDojo) then
        return tipInfo
    end
    if checkNumber(placeDojo.unlockCountdown) >= 0 then
        tipInfo = self:GetTimeMHS(placeDojo.unlockCountdown)
    end
    return tipInfo
end

function MidFestivalHomeDojo:GetTimeMHS(seconds)
    seconds = math.abs(seconds)
    local h = math.floor(seconds / 3600)
    local d = checkInt(math.floor(h / 24))
    if d > 0 then
        return localize("还剩_day_天后解锁", {_day_ = d})
    end

    if h >= 1 then
        return localize("还剩_hour_小时后解锁", {_hour_ = h})
    end

    return localize("不足1小时后解锁")
end

function MidFestivalHomeDojo:UpdateBossHurtRedPoint(hasRedPoint)
    local num = hasRedPoint and 0 or -1
    if num ~= self.bossHurtTips then
        self.bossHurtTips = num
        Events.Broadcast(Constants.EventNames.CommonActivityBossHurtTipsChanged)
    end
end

function MidFestivalHomeDojo:UpdateAchievementTaskTips(achievementTaskTips)
    self.achievementTaskTips = achievementTaskTips
end

function MidFestivalHomeDojo:GetAchievementTaskTips()
    return self.achievementTaskTips
end

function MidFestivalHomeDojo:GetBossHurtTips()
    return self.bossHurtTips
end

function MidFestivalHomeDojo:GetNewItemInSubList(subList)
    for _, subQuest in ipairs(subList) do
        if checkNumber(self.mainQuestId) == checkNumber(subQuest.unlockLevel) then
            return subQuest
        end
    end
    return nil
end

function MidFestivalHomeDojo:IsRecordQuestPass(questId)
    for _, quest in ipairs(checkTable(self.repaintingQuest)) do
        if checkNumber(quest.questId) == checkNumber(questId) then
            return checkNumber(quest.isPassed) == 1
        end
    end
    return false
end



function MidFestivalHomeDojo:RemoveTimer()
    if isNotNull(self.timer) then
        CDTimerModule.GetInstance():RemoveCD(self.timer)
        self.timer = nil
    end
end

function MidFestivalHomeDojo:StartTimeDown()
    self:RemoveTimer()
    self.timer = CDTimerModule.GetInstance():AddCD(1, function(_, _, delta)
        -- 体力已经恢复满，停止倒计时
        if self:IsFull() then
            self:Broadcast(true, 0, 0)
            self:RemoveTimer()
            return
        end

        self:SubCDTime(delta)

    end, CountDownTime, true, true)
end

function MidFestivalHomeDojo:IsFull()
    local midFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local entryId = midFestivalComponent:GetActivityEnergyId()
    local ownCount = GoodsUtils.GetThingNo(entryId)
    return ownCount >= self._hpMax
end

function MidFestivalHomeDojo:SubCDTime(delta)
    self.hpData.lastCdTime = checkNumber(self.hpData.lastCdTime) - checkNumber(delta)
    --printInfo("CHANG DEBUG: 倒计时:" .. checkString(self.hpData.lastCdTime))
    -- 通知注册者数值发生了变化
    local midFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local entryId = midFestivalComponent:GetActivityEnergyId()
    local goodsNum = GoodsUtils.GetThingNo(entryId)
    self:Broadcast(false, checkInt(self.hpData.lastCdTime), checkInt(self.hpData.lastCdTime + (self._hpMax - goodsNum - 1) * checkInt(self._hpRecoverSeconds)))
    if self.hpData.lastCdTime < 0 then
        -- 开始恢复体力
        local mod = (math.abs(self.hpData.lastCdTime) - 1) % self._recoveryHpPerTime    -- 溢出mod秒
        local left = (math.abs(self.hpData.lastCdTime) - 1) / self._recoveryHpPerTime   -- 溢出left体力
        local recoverCount = (left + 1) * self._recoveryHpPerTime

        --printInfo("CHANG DEBUG：实际恢复的体力:" .. checkString(recoverCount))
        local midFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
        local entryId = midFestivalComponent:GetActivityEnergyId()
        GoodsUtils.DrawRewards({
            {
                goodsId = entryId,
                num = recoverCount
            }
        }, true)

        -- 重置倒计时
        self.hpData.lastCdTime = self._hpRecoverSeconds - mod
        self:StartTimeDown()
    end
end

function MidFestivalHomeDojo:Broadcast(isFull, cd, totalCD)
    Events.Broadcast("EVENT_CONSTANT_COUNTDOWN_FULL", isFull, cd, totalCD)
end

---取得当前id 双旦活动参数表
function MidFestivalHomeDojo:GetConfigParamsById(id)
    ---@type BaseArgVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6084, "MidFestivalActivityParameterVo", id)
    if vo == nil then
        printError("双旦活动参数表 中未找到 %s", id)
        return 0
    end
    return vo.num
end

return MidFestivalHomeDojo